#include "ksNativeNoteProgramService.h"
#include "ksNativeNoteProgramAbi.h"
#include <array>
#include <vector>
#include <cstdlib>
#include <cstring>
#include <iostream>
#include <new>
#include <stdexcept>
namespace{bool tracking=false;uint64_t allocations=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool v,const char*m){if(!v)throw std::runtime_error(m);}
int main(){try{using T=ks::NativeNoteProgramService;using K=T::Kind;std::vector<uint8_t>m(1<<24);uint64_t graphs=0,phases=0,rejects=0,reads=0,writes=0;uint32_t components=0;
for(unsigned kind=0;kind<2;++kind)for(unsigned note=0;note<128;++note)for(unsigned bank:{0u,5u,6u}){std::fill(m.begin()+0x15000,m.begin()+0x30000,uint8_t(0));const auto wide=[&](unsigned a,uint32_t v){for(unsigned n=0;n<4;++n)m[a+n]=uint8_t(v>>(24-8*n));};const unsigned part=2,controls=0x174ae + 20*part,base=0x160d2+334*part,generated=0x839000+unsigned(uint8_t(bank-5))*0x3200+unsigned(uint8_t(note-36))*256;m[0x17526]=m[0x16798]=part;m[0x174a6]=4;wide(controls,0x18000);m[controls+14]=64;for(unsigned patch:{0x18000u,generated}){for(unsigned i=0;i<256;++i)m[patch+i]=0;m[patch]=16;m[patch+4]=64;m[patch+58]=m[patch+61]=m[patch+66]=64;m[patch+79]=0x35;m[patch+78]=m[patch+147]=2;m[patch+80]=7;m[patch+173]=8;}m[92078+part*2]=uint8_t(bank);m[92079+part*2]=0;m[0x1755c]=1;m[0x168fc+249]=1;m[0x168fc+219]=uint8_t(note);m[0x168fc+220]=1;m[0x168fc+221]=2;for(unsigned i=0;i<32;++i)m[0x1532e + i]=uint8_t(i*17);m[0x159f2]=0xff;m[0x159f3]=0xff;
unsigned count=0;int previous=-1;tracking=true;{T t(K(kind),{uint16_t(0x6400|note)});while(!t.complete()){struct Unowned{};check(!t.task<Unowned>(),"Unknown note program task query");const auto cost=t.nextClocks(previous);check(cost>0,"Program pure stalled");std::array<unsigned char,sizeof(T)>saved{};std::memcpy(saved.data(),&t,sizeof(T));unsigned callbacks=0;check(t.advanceBefore(cost-1,[&](uint32_t,unsigned){++callbacks;return uint8_t(0);},[&](uint32_t,uint8_t,unsigned){++callbacks;},previous)==0&&!callbacks&&!std::memcmp(saved.data(),&t,sizeof(T)),"Program budget changed object");++rejects;const auto read=[&](uint32_t a,unsigned dt){check(a<(1u<<24)&&dt<=cost,"Program pure read bound");++reads;return a==0x400004||a==0x600004?uint8_t(255):a==0x60000a?uint8_t(0x12):a==0x60000c?uint8_t(0x34):a==0x60000e?uint8_t(8):m[a];};const auto write=[&](uint32_t a,uint8_t v,unsigned dt){check(a<(1u<<24)&&dt<=cost&&!(a>=0xfff000&&a<0xfffc00),"Program pure write bound");++writes;m[a]=v;previous=a<0x400000?int(a):-1;};check(t.advanceBefore(cost,read,write,previous)==cost,"Program pure admission");if(t.effect().write)previous=-1;check(++count<1000000,"Program pure did not complete");++phases;}
const auto&s=t.summary();const bool allowed=kind||bank<=4||(note>=36&&note<=84);check(s.played==allowed,"Program note-range oracle");if(allowed)check(m[base+314]==note,"Program last note oracle");uint32_t ref=0;for(unsigned n=0;n<4;++n)ref=(ref<<8)|m[controls+n];check(ref==0x18000,"Program original reference restore oracle");if(s.temporary)check(s.selectTask->patchReference()==generated,"Program sample address oracle");struct A{std::array<uint32_t,7>values{};uint8_t flags=0;};A a;projectNativeNoteProgram(a,t);components|=t.components();}tracking=false;++graphs;}
check(components==15&&!allocations,"Program pure coverage/heap");std::cout<<"PASS Pure NativeNoteProgram graphs="<<graphs<<" phases="<<phases<<" whole_object_budget_rejects="<<rejects<<" reads="<<reads<<" writes="<<writes<<" components="<<components<<" sizeof="<<sizeof(T)<<" allocations="<<allocations<<'\n';return 0;
}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
